export function createCinematicTransport({window:win,frame,timeoutMs=60000}){
  let serial=0,ready=false,expectedMap=null,disposed=false;const pending=new Map(),eventListeners=new Set();
  const rejectAll=message=>{for(const job of pending.values()){clearTimeout(job.timer);job.reject(new Error(message));}pending.clear();};
  const post=job=>{
    if(!ready||job.sent||!frame.contentWindow)return;
    job.sent=true;
    try{frame.contentWindow.postMessage(job.message,win.location.origin);}catch(error){pending.delete(job.message.requestId);clearTimeout(job.timer);job.reject(error);}
  };
  const receive=event=>{
    const reply=parseCinematicReply(event,{source:frame.contentWindow,origin:win.location.origin});if(!reply)return;
    if(reply.requestId==='host-ready'){
      if(!reply.ok||typeof reply.ready!=='boolean'||!Object.hasOwn(mapCharacters,reply.mapId)||(expectedMap&&reply.mapId!==expectedMap))return;
      ready=reply.ready;if(ready)for(const job of pending.values())post(job);return;
    }
    if(['actor-selection','actor-edited','subtitle-selection','subtitle-edited','existing-selection','camera-control-state'].includes(reply.requestId)){if(!ready||!reply.ok||!Object.hasOwn(mapCharacters,reply.mapId)||(expectedMap&&reply.mapId!==expectedMap))return;for(const listener of eventListeners)try{listener(reply);}catch{/* A view listener never owns the transport. */}return;}
    const job=pending.get(reply.requestId);if(!job?.sent)return;pending.delete(reply.requestId);clearTimeout(job.timer);if(reply.ok)job.resolve(reply);else job.reject(Object.assign(new Error(reply.error??'Preview command failed'),{errors:reply.errors}));
  };
  win.addEventListener('message',receive);
  const send=(command,payload={})=>new Promise((resolve,reject)=>{
    if(disposed){reject(new Error('Studio closed'));return;}
    const requestId='studio-'+(++serial),timer=setTimeout(()=>{pending.delete(requestId);reject(new Error('장면 준비 시간이 초과되었습니다. 화면의 오류를 확인한 뒤 장면 열기를 다시 눌러 주세요.'));},timeoutMs);
    const job={resolve,reject,timer,message:cinematicCommand(command,requestId,payload),sent:false};pending.set(requestId,job);post(job);
  });
  send.reset=(mapId,message='맵이 변경되었습니다. 장면 열기를 눌러 주세요.')=>{ready=false;expectedMap=mapId??null;rejectAll(message);};
  send.onEvent=listener=>{if(disposed)return ()=>{};eventListeners.add(listener);return ()=>eventListeners.delete(listener);};
  send.dispose=()=>{if(disposed)return;disposed=true;win.removeEventListener('message',receive);eventListeners.clear();rejectAll('Studio closed');};return send;
}

